function fullListPromotionStatistics(sourceRows, summary, startDate, reportSignalDate) {
  // Called only after the original window, summary and CSV SHA bindings pass.
  const days = summary.daily_summaries.filter(day => day.signal_date >= startDate && day.signal_date <= reportSignalDate && day.signal_date <= summary.as_of_date);
  const windowRows = sourceRows.filter(row => row.signal_date >= startDate && row.signal_date <= reportSignalDate && row.signal_date <= summary.as_of_date);
  executableProfitExpect(new Set(days.map(day => day.signal_date)).size === days.length, "全名单统计日期重复");
  let count = 0, verified = 0, hits = 0;
  for (const day of days) {
    const rows = windowRows.filter(row => row.signal_date === day.signal_date);
    const ranks = rows.map(row => Number(row.promotion_rank)).sort((a,b) => a-b);
    executableProfitExpect(rows.length === day.rows && new Set(rows.map(row => row.ts_code)).size === rows.length
      && rows.every(row => /^\d{6}\.(SH|SZ|BJ)$/.test(row.ts_code))
      && ranks.every((rank, i) => rank === i + 1), "全名单统计成员缺失或重复");
    const known = rows.filter(row => row.continuation_limit_up_hit !== "" && row.continuation_limit_up_hit != null);
    executableProfitExpect(rows.every(row => row.exec_date === day.exec_date
      && (["PENDING_T", "MISSING_T_TRUTH"].includes(row.validation_status)
        ? row.continuation_limit_up_hit === "" || row.continuation_limit_up_hit == null
        : ["0", "1"].includes(String(row.continuation_limit_up_hit))))
      && known.length === day.t_validated_rows && (!known.length || day.exec_date <= summary.as_of_date), "全名单T日验证状态或数量不一致");
    count += rows.length;
    verified += known.length;
    hits += known.reduce((total, row) => total + Number(row.continuation_limit_up_hit), 0);
  }
  executableProfitExpect(count === windowRows.length, "全名单统计存在未绑定日期");
  return {count, verified, hits, hit_rate: verified ? hits / verified : null};
}
